  void Run(){var screen=E(root,"run-screen");if(narrow)RunProgress(screen);var lower=E(screen,"hero-corner");var skills=E(lower,"row abilities");string[] names={"Echo Tasks","Task Speed","Movement Speed","Prospector","Echo Resonance"};string[] times={"51s","10s","9s","1:21","2:06"};for(int i=0;i<5;i++){int index=i;var recipe=m.Buffs.FirstOrDefault(b=>b.name.Replace("|","").Replace(" ","").Equals(names[i].Replace(" ",""),StringComparison.OrdinalIgnoreCase)||b.title==names[i]);var b=B(skills,"",()=>{m.AutoCast[index]=!m.AutoCast[index];Rebuild();},"ability"+(i==4?" last-ability":""));b.tooltip=names[i]+" · "+T(m.AutoCast[i]?"auto":"manual");Icon(b,recipe?recipe.buffIcon:m.Run.portrait,30);L(b,times[i],"small strong");b.Add(new BorderProgress(.25f+i*.14f));if(m.AutoCast[i]){var mark=Icon(b,m.Run.buffs.autoCast,32);mark.AddToClassList("ability-echo");mark.tintColor=m.Run.buffs.autoCastTint;}}var hero=E(lower,"surface hero");var content=E(hero,"row hero-content");var portrait=E(content,"hero-portrait-frame");Icon(portrait,m.Run.portrait,64);var vitals=E(content,"hero-vitals");var top=E(vitals,"row hero-vital-row");
