  public string Validate(){int images=0,invalid=0;root.Query<Image>().ForEach(i=>{if(i.sprite){images++;if(i.scaleMode!=ScaleMode.ScaleToFit)invalid++;}});var fs=root.Q<ScrollView>("ingredients-scroll");var cs=root.Q<ScrollView>("collection-scroll");var work=root.Q<VisualElement>("workspace");return $"Editor-only sample; Play={EditorApplication.isPlaying}\nTheme={dark}; locale={locale}; large={large}; narrow={narrow}\nFoods={m.Foods.Length}; resources={m.Resources.Length}; buffs={m.Buffs.Length}; boons={m.Boons.Length}\nImages={images}; invalid aspect modes={invalid}\nRoot={root.worldBound}; workspace={work?.worldBound}\nIngredients viewport={fs?.contentViewport.worldBound}; scroll range={fs?.verticalScroller.highValue}\nCollection viewport={cs?.contentViewport.worldBound}; scroll range={cs?.verticalScroller.highValue}\n";}
