 internal sealed class BorderProgress:VisualElement
 {
  static readonly CustomStyleProperty<Color> Accent=new("--ring-color"),Track=new("--ring-track");Color accent,track;
  public BorderProgress(float value){AddToClassList("border-progress");pickingMode=PickingMode.Ignore;RegisterCallback<CustomStyleResolvedEvent>(e=>{e.customStyle.TryGetValue(Accent,out accent);e.customStyle.TryGetValue(Track,out track);MarkDirtyRepaint();});generateVisualContent+=ctx=>{float w=contentRect.width-2,h=contentRect.height-2;if(w<=0||h<=0)return;var pts=new[]{new Vector2(1+w/2,1),new Vector2(1+w,1),new Vector2(1+w,1+h),new Vector2(1,1+h),new Vector2(1,1),new Vector2(1+w/2,1)};var p=ctx.painter2D;p.lineWidth=2;Draw(p,pts,2*(w+h),track);Draw(p,pts,2*(w+h)*Mathf.Clamp01(value),accent);};}
  static void Draw(Painter2D p,Vector2[] pts,float remaining,Color color){p.strokeColor=color;p.BeginPath();p.MoveTo(pts[0]);for(int i=1;i<pts.Length&&remaining>0;i++){float length=Vector2.Distance(pts[i-1],pts[i]);p.LineTo(Vector2.Lerp(pts[i-1],pts[i],Mathf.Min(remaining/length,1)));remaining-=length;}p.Stroke();}
 }
